#!/usr/bin/env node
/**
 * ULS App Creator
 * 
 * Creates a new ULS app bundle with full LESS compilation support.
 * 
 * Usage:
 *   npm run create uls-app <appName>
 * 
 * Example:
 *   npm run create uls-app admin
 */

const fs = require('fs');
const path = require('path');
const { createRequire } = require('module');

const CONFIG_FILE_NAMES = [
  'uls.config.cjs',
  'uls.config.js',
  'uls.override.config.cjs',
  'uls.override.config.js',
];

const ENTRY_FILE_NAME = 'uls-overrides.less';

// ============================================================================
// Main Execution
// ============================================================================

(async function run() {
  try {
    const args = process.argv.slice(2);
    
    // Parse command: npm run create uls-app <appName>
    // When called via npm run, args will be: ['uls-app', 'admin']
    // When called directly: node create-uls-app.js create uls-app admin, args will be: ['create', 'uls-app', 'admin']
    let appName;
    
    if (args.length >= 2 && args[0] === 'create' && args[1] === 'uls-app') {
      // Called directly: node create-uls-app.js create uls-app admin
      appName = args[2];
    } else if (args.length >= 2 && args[0] === 'uls-app') {
      // Called via npm run: npm run create uls-app admin
      appName = args[1];
    } else {
      console.error('❌ Invalid command format');
      console.log('\nUsage: npm run create uls-app <appName>');
      console.log('Example: npm run create uls-app admin');
      process.exit(1);
    }
    
    if (!appName) {
      console.error('❌ App name is required');
      console.log('\nUsage: npm run create uls-app <appName>');
      process.exit(1);
    }

    // Validate appName
    if (!validateAppName(appName)) {
      console.error(`❌ Invalid app name: "${appName}"`);
      console.log('\nApp name must be:');
      console.log('  - Lowercase only');
      console.log('  - No spaces');
      console.log('  - Alphanumeric, hyphens, or underscores only');
      console.log('  - Not "default" (reserved)');
      process.exit(1);
    }

    const projectRoot = process.cwd();
    const { config } = await loadConfig(projectRoot);
    const stylesPath = config?.stylesPath || 'src/styles/uls';
    const appDir = path.resolve(projectRoot, stylesPath, appName);

    // Check if app already exists
    if (fs.existsSync(appDir)) {
      console.error(`❌ App "${appName}" already exists at: ${path.relative(projectRoot, appDir)}`);
      console.log('   Delete the existing app folder first or choose a different name.');
      process.exit(1);
    }

    console.log(`\n🚀 Creating ULS app: ${appName}\n`);

    // Create folder structure
    ensureDirectories(appDir);

    // Generate LESS files
    generateLessFiles(appDir);

    // Seed override structure
    seedOverrides(appDir, config);

    // Update package.json
    updatePackageJson(projectRoot, appName);

    // Update uls.config.cjs
    updateUlsConfig(projectRoot, appName, config);

    console.log(`\n✅ ULS app "${appName}" created successfully!\n`);
    console.log('📁 Created structure:');
    console.log(`   ${path.relative(projectRoot, appDir)}/`);
    console.log(`   ├── uls-base.less`);
    console.log(`   ├── uls-styles.less`);
    console.log(`   ├── uls-master.less`);
    console.log(`   └── overrides/`);
    console.log('\n📝 Updated files:');
    console.log('   • package.json (added ulsDev:<appName> script)');
    console.log('   • uls.config.cjs (added app to apps array)');
    console.log('\n🎯 Next steps:');
    console.log(`   1. Run: npm run ulsBuild:${appName} (to compile CSS)`);
    console.log(`   2. Run: npm run ulsDev:${appName} (to watch for changes)`);
    console.log(`   3. Customize: ${path.relative(projectRoot, path.join(appDir, 'overrides'))}/\n`);

  } catch (error) {
    console.error('\n❌ Error creating ULS app:', error.message);
    if (error.stack) {
      console.error('\nStack trace:', error.stack);
    }
    process.exit(1);
  }
})();

// ============================================================================
// Validation
// ============================================================================

function validateAppName(name) {
  if (!name || name.trim() === '') {
    return false;
  }

  // Must be lowercase
  if (name !== name.toLowerCase()) {
    return false;
  }

  // No spaces
  if (name.includes(' ')) {
    return false;
  }

  // Only alphanumeric, hyphens, underscores
  if (!/^[a-z0-9_-]+$/.test(name)) {
    return false;
  }

  // Not "default" (reserved)
  if (name === 'default') {
    return false;
  }

  return true;
}

// ============================================================================
// Config Loading
// ============================================================================

async function loadConfig(projectRoot) {
  for (const filename of CONFIG_FILE_NAMES) {
    const filePath = path.join(projectRoot, filename);
    if (!fs.existsSync(filePath)) {
      continue;
    }

    try {
      delete require.cache[require.resolve(filePath)];
      return {
        config: require(filePath),
        filePath,
      };
    } catch (err) {
      console.warn(`\n⚠️  Warning: Could not load config file ${filename}: ${err.message}`);
      return { config: null, filePath: null };
    }
  }

  return { config: null, filePath: null };
}

// ============================================================================
// Directory Creation
// ============================================================================

function ensureDirectories(appDir) {
  const dirs = [
    appDir,
    path.join(appDir, 'overrides'),
    path.join(appDir, 'overrides', 'base'),
    path.join(appDir, 'overrides', 'elements'),
    path.join(appDir, 'overrides', 'collections'),
    path.join(appDir, 'overrides', 'modules'),
    path.join(appDir, 'overrides', 'themes'),
  ];

  dirs.forEach((dir) => {
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
      console.log(`📁 Created directory: ${path.relative(process.cwd(), dir)}`);
    }
  });
}

// ============================================================================
// LESS File Generation
// ============================================================================

function generateLessFiles(appDir) {
  // Generate uls-base.less
  const basePath = path.join(appDir, 'uls-base.less');
  fs.writeFileSync(basePath, getBaseFileContent(), 'utf8');
  console.log(`📝 Created: ${path.relative(process.cwd(), basePath)}`);

  // Generate uls-styles.less
  const stylesPath = path.join(appDir, 'uls-styles.less');
  fs.writeFileSync(stylesPath, getStylesFileContent(), 'utf8');
  console.log(`📝 Created: ${path.relative(process.cwd(), stylesPath)}`);

  // Generate uls-master.less
  const masterPath = path.join(appDir, 'uls-master.less');
  fs.writeFileSync(masterPath, getMasterFileContent(), 'utf8');
  console.log(`📝 Created: ${path.relative(process.cwd(), masterPath)}`);
}

