function getMasterFileContent() {
  return `// ==========================================================================
// ULS Master Entry (Per-App)
// ==========================================================================
// Import order:
// 1. ULS styles (base + components)
// 2. App overrides (highest priority)
// ==========================================================================

@import "./uls-styles.less";
@import "./overrides/uls-overrides.less";
`;
}

// ============================================================================
// Override Seeding
// ============================================================================

function seedOverrides(appDir, config) {
  const overridesDir = path.join(appDir, 'overrides');
  const entryPath = path.join(overridesDir, ENTRY_FILE_NAME);

  // Create override entry file
  const entryTemplate = `// ==========================================================================
// ULS Override Entry Point
// ==========================================================================
// Automatically maintained by the ULS generators. Override files are grouped
// by type and imported below. New overrides will be inserted above the AUTO
// markers - do not remove them.
// ==========================================================================

// Base system overrides (variables, mixins, root config)
@import (optional) "base/root-config.overrides";
// ::ULS-AUTO-BASE::

// Element overrides (buttons, inputs, etc.)
// ::ULS-AUTO-ELEMENTS::

// Collection overrides (cards, accordions, etc.)
// ::ULS-AUTO-COLLECTIONS::

// Module overrides (dialogs, tables, etc.)
// ::ULS-AUTO-MODULES::

// Theme overrides
// ::ULS-AUTO-THEMES::

`;
  fs.writeFileSync(entryPath, entryTemplate, 'utf8');
  console.log(`📝 Created: ${path.relative(process.cwd(), entryPath)}`);

  // Try to copy from default app first, otherwise seed from ULS package
  const projectRoot = process.cwd();
  const stylesPath = config?.stylesPath || 'src/styles/uls';
  const defaultAppDir = path.resolve(projectRoot, stylesPath, 'default');
  const defaultOverridesDir = path.join(defaultAppDir, 'overrides');

  if (fs.existsSync(defaultOverridesDir)) {
    // Copy override structure from default app
    copyOverrideStructure(defaultOverridesDir, overridesDir);
    console.log('🧩 Copied override structure from default app');
  } else {
    // Seed from ULS package templates
    const seeded = seedFromUlsPackage(overridesDir);
    if (seeded) {
      console.log('🧩 Seeded override templates from ULS package');
    }
  }

  // Create root-config.overrides.less if it doesn't exist
  const rootOverridePath = path.join(overridesDir, 'base', 'root-config.overrides.less');
  if (!fs.existsSync(rootOverridePath)) {
    const rootOverrideContent = `// ==========================================================================
// ROOT CONFIG OVERRIDES
// ==========================================================================
// Customize global CSS variables or LESS tokens here. Everything defined in
// this file loads immediately after the core ULS bundle.
// ==========================================================================

:root {
  // --uls-global-scale: 1.125;
  // --uls-primary-color: #ff0000;
}

// Example LESS override:
// @font-size14: 15px;
`;
    fs.writeFileSync(rootOverridePath, rootOverrideContent, 'utf8');
    console.log(`📝 Created: ${path.relative(process.cwd(), rootOverridePath)}`);
  }
}

function copyOverrideStructure(sourceDir, destDir) {
  if (!fs.existsSync(sourceDir)) {
    return false;
  }

  let copied = false;
  const entries = fs.readdirSync(sourceDir, { withFileTypes: true });

  entries.forEach((entry) => {
    const sourcePath = path.join(sourceDir, entry.name);
    const destPath = path.join(destDir, entry.name);

    if (entry.isDirectory()) {
      if (!fs.existsSync(destPath)) {
        fs.mkdirSync(destPath, { recursive: true });
      }
      if (copyOverrideStructure(sourcePath, destPath)) {
        copied = true;
      }
    } else {
      // For the entry file, copy it if source has more content (full override file)
      // Otherwise keep the template we already created
      if (entry.name === ENTRY_FILE_NAME) {
        const sourceContent = fs.readFileSync(sourcePath, 'utf8');
        const destContent = fs.existsSync(destPath) ? fs.readFileSync(destPath, 'utf8') : '';
        // Copy if source file is more comprehensive (has more imports than just the template)
        // Check if source has more than just the basic template structure
        const sourceHasFullImports = sourceContent.split('@import').length > 5; // More than just template
        const destIsTemplate = destContent.includes('::ULS-AUTO-BASE::') && 
                               destContent.split('@import').length <= 3;
        
        if (sourceHasFullImports && destIsTemplate) {
          fs.copyFileSync(sourcePath, destPath);
          copied = true;
        }
      } else if (!fs.existsSync(destPath)) {
        fs.copyFileSync(sourcePath, destPath);
        copied = true;
      }
    }
  });

  return copied;
}

function seedFromUlsPackage(destOverridesRoot) {
  const sourceRoot = findDefaultOverridesRoot();
  if (!sourceRoot) {
    return false;
  }

  return copyOverrideStructure(sourceRoot, destOverridesRoot);
}

function findDefaultOverridesRoot() {
  const candidates = [
    path.resolve(__dirname, '../src/styles/uls-overrides/less/uls-primereact'),
    path.resolve(__dirname, '../src/styles/uls-overrides'),
    path.resolve(process.cwd(), 'node_modules/uls/styles/uls-overrides/less/uls-primereact'),
    path.resolve(process.cwd(), 'node_modules/uls-v2/src/styles/uls-overrides/less/uls-primereact'),
  ];

  return candidates.find((candidate) => {
    try {
      return fs.existsSync(candidate) && fs.statSync(candidate).isDirectory();
    } catch (err) {
      return false;
    }
  }) || null;
}

// ============================================================================
// package.json Update
// ============================================================================

function updatePackageJson(projectRoot, appName) {
  const packageJsonPath = path.join(projectRoot, 'package.json');
  
  if (!fs.existsSync(packageJsonPath)) {
    console.warn('⚠️  package.json not found, skipping script update');
    return;
  }

  try {
    // Read and parse package.json
    const content = fs.readFileSync(packageJsonPath, 'utf8');
    const packageJson = JSON.parse(content);

    // Ensure scripts object exists
    if (!packageJson.scripts) {
      packageJson.scripts = {};
    }

    // Check if script already exists
    const scriptKey = `ulsDev:${appName}`;
    if (packageJson.scripts[scriptKey]) {
      console.log(`⚠️  Script "${scriptKey}" already exists, skipping update`);
      return;
    }

    // Add new script
    packageJson.scripts[scriptKey] = `ULS_APP=${appName} npm run ulsDev:watch`;

    // Write back with preserved formatting (2 spaces indentation)
    const updatedContent = JSON.stringify(packageJson, null, 2) + '\n';
    fs.writeFileSync(packageJsonPath, updatedContent, 'utf8');
    console.log(`📝 Updated: package.json (added ${scriptKey} script)`);

  } catch (error) {
    console.error(`❌ Failed to update package.json: ${error.message}`);
    throw error;
  }
}

// ============================================================================
// uls.config.cjs Update
// ============================================================================

function updateUlsConfig(projectRoot, appName, existingConfig) {
  const configPath = path.join(projectRoot, 'uls.config.cjs');
  
  if (!fs.existsSync(configPath)) {
    console.warn('⚠️  uls.config.cjs not found, skipping config update');
    return;
  }

  try {
    // Read existing config file
    const content = fs.readFileSync(configPath, 'utf8');
    
    // Check if app is already in the apps array
    if (existingConfig && Array.isArray(existingConfig.apps)) {
      if (existingConfig.apps.includes(appName)) {
        console.log(`⚠️  App "${appName}" already in uls.config.cjs apps array, skipping update`);
        return;
      }
    }

    // Update the apps array in the config file
    // Use regex to find and update the apps array while preserving formatting
    let updatedContent = content;
    
    // Pattern 1: apps: ['default'] or apps: ["default"]
    const pattern1 = /apps:\s*\[(['"])([^'"]+)\1\s*\]/;
    if (pattern1.test(updatedContent)) {
      updatedContent = updatedContent.replace(
        pattern1,
        (match, quote, existingApp) => {
          return `apps: [${quote}${existingApp}${quote}, ${quote}${appName}${quote}]`;
        }
      );
    } else {
      // Pattern 2: apps: ['default', 'app2', ...] (multi-item array)
      const pattern2 = /apps:\s*\[([^\]]+)\]/;
      if (pattern2.test(updatedContent)) {
        updatedContent = updatedContent.replace(
          pattern2,
          (match, appsContent) => {
            // Check if appName is already in the array (handle both single and double quotes)
            const normalizedContent = appsContent.replace(/['"]/g, '');
            if (normalizedContent.includes(appName)) {
              return match; // Already exists
            }
            // Append to the array (preserve existing quote style)
            const hasDoubleQuotes = appsContent.includes('"');
            const quote = hasDoubleQuotes ? '"' : "'";
            // Trim trailing whitespace and add new item
            const trimmed = appsContent.trim();
            return `apps: [${trimmed}, ${quote}${appName}${quote}]`;
          }
        );
      } else {
        // Pattern 3: No apps array found, add it before the closing brace
        // Find the last property before the closing brace
        const lastBraceIndex = updatedContent.lastIndexOf('};');
        if (lastBraceIndex !== -1) {
          const beforeBrace = updatedContent.substring(0, lastBraceIndex).trimEnd();
          const afterBrace = updatedContent.substring(lastBraceIndex);
          // Add comma if there are other properties
          const needsComma = !beforeBrace.endsWith('{') && !beforeBrace.endsWith(',');
          updatedContent = `${beforeBrace}${needsComma ? ',' : ''}\n  apps: ['${appName}'],\n${afterBrace}`;
        }
      }
    }

    fs.writeFileSync(configPath, updatedContent, 'utf8');
    console.log(`📝 Updated: uls.config.cjs (added "${appName}" to apps array)`);

  } catch (error) {
    console.error(`❌ Failed to update uls.config.cjs: ${error.message}`);
    throw error;
  }
}

